export interface Usage { inputTokens: number; cacheTokens: number; outputTokens: number }
export function cost(usage: Usage): number {
  const uncached = usage.inputTokens - usage.cacheTokens;
  return uncached * 0.75 + usage.cacheTokens * 0.075 + usage.outputTokens * 3.75;
}

import { cost, type Usage } from "./cost.js";
export function recordUsage(usage: Usage): number {
  if (usage.inputTokens < 0 || usage.cacheTokens < 0 || usage.outputTokens < 0)
    throw new Error("Token counts must be nonnegative.");
  if (usage.cacheTokens > usage.inputTokens)
    throw new Error("Cached input is a subset of input.");
  return cost(usage);
}

export interface Usage { inputTokens: number; cacheTokens: number; outputTokens: number }
export function cost(usage: Usage): number {
  const uncached = usage.inputTokens - usage.cacheTokens;
  if (uncached === 0) return 0;
  return uncached * 0.75 + usage.cacheTokens * 0.075 + usage.outputTokens * 3.75;
}

